INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'cf61ba27-bd0d-5390-a282-5d2b25c8fa4d'::uuid, '884d3331-cc17-5181-beef-7e793952941f'::uuid, 'LA DOLCE VITA DARBESQUE', 'Seaside Luxury Living puise son essence du Gated Community offrant à ses résidents un espace de vie fermé et entièrement sécurisé. Le parti-pris des concepteurs a été de porter le plus grand soin à l''idée architecturale: des résidences au profil bas R+2 offrant une vue imprenable sur l''horizon, des pools orientés sud pour de longues heures d''ensoleillement et de baignade, le tout embelli de palmiers et d''arbustes d''ornement. Le feng Shui pensé transforme Seaside Luxury Living en un lieu enclin au bien-être, vous invitant à la détente et à la vie extérieure.', 'Dar Bouazza', NULL, 'des privilégiés Perché face à la mer, Seaside Luxury Living bénéficie d''un emplacement très convoité entre mer et terre', '20220', 'MA', NULL, NULL, 'immobilier', 'residentiel', 'residentiel', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-23.jpg', $j$["https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-23.jpg", "https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-22.jpg", "https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-21.jpg", "https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-20.jpg", "https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-19.jpg", "https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-18.jpg", "https://alidari.ma/wp-content/uploads/2022/07/seaside-slide-17.jpg", "https://alidari.ma/wp-content/uploads/2022/07/s