INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '503e3f65-6d58-5ea9-9106-8daf7b70c95c'::uuid, '4695cecd-b348-51d6-bb14-7d92e4ae0980'::uuid, 'Politique d''utilisation des cookies, Immobilier Neuf/Terrains Maroc', 'ut statistique afin de procéder à des analyses de fréquentation du Site. Le site Alliances Darna collecte diverses données grâce à l''utilisation des cookies, relatives notamment aux caractéristiques du système d''exploitation, du navigateur ou du terminal (ordinateur, tablette ou téléphone mobile) que vous utilisez, des données relatives à votre localisation ou encore des données relatives à vos différentes interactions avec le contenu de Alliances Darna. Lors de votre navigation sur le site Alliances Darna, vous acceptez de recevoir des cookies et la présente utilisation des cookies. Un cookie ne permet pas de vous identifier personnellement. En revanche, il enregistre des informations relatives à la navigation de votre ordinateur sur le site (les pages que vous avez consultées, la date et l''heure de la consu', NULL, NULL, 'ou encore des données relatives à vos différentes interactions avec le contenu de Alliances Darna. Lors de votre navigat', NULL, 'MA', NULL, NULL, 'immobilier', 'lotissement', 'lotissement', 'sur_plan', 'en_commercialisation', 15, NULL, NULL, 'https://alliancesdarna.ma/wp-content/uploads/ESCDA-24-FR-1.png', $j$["https://alliancesdarna.ma/wp-content/uploads/ESCDA-24-FR-1.png"]$j$::jsonb, 'Lot de terrain', 'Jardin ,  Espace vert', NULL, false, NULL, NULL, NULL, 'MAD', NULL, '4695cecd-b348-51d6-bb14-7d92e4ae0980', 'Alliances Darna', 'https://alliancesdarna.ma/', $j$[]$