INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '96d55c35-b4f0-5faf-9986-cbf2d60f7255'::uuid, '4695cecd-b348-51d6-bb14-7d92e4ae0980'::uuid, 'Alliances Darna : Immobilier Neuf Maroc, Lot de Terrain Maroc, Projet Immobilier Neuf', 'Bienvenue chez ALLIANCES DARNA ! Depuis 2007, ALLIANCES DARNA s''est affirmée en tant que leader dans le domaine du développement de logements économiques et moyen standing. Notre engagement envers la création de logements de qualité, bien situés et accessibles, a permis à notre entreprise de devenir une référence incontournable sur ce marché. NOTRE MISSION Notre mission est de répondre aux besoins de notre clientèle en proposant des programmes immobiliers intégrés et complets. Chaque projet est soigneusement conçu pour offrir bien plus que des logements : nous créons des lieux de vie qui favorisent la mixité sociale et s''intègrent harmonieusement dans leurs environnements respectifs. NOTRE APPROCHE Chez ALLIANCES DARNA, nous croyons en la durabilité à tous les niveaux. Nos projets sont le fruit d''une étude minutieuse visant à créer des espaces de vie qui perdureront dans le temps. Nous concevons des logements qui allient confort, fonctionnalité et esthétique, tout en prenant en compte les besoins évoluant de nos clients. NOS RÉALISATIONS Au fil des années, nous avons fièrement contribué à la réalisation de nombreux logements. Chaque projet est une démonstration de notre engagement', NULL, 'immobilier et sont engagés à donner vie à', '16 rue Ali Abderrazak', NULL, 'MA', NULL, NULL, 'immobilier', 'lotissement', 'lotissement', 'livre', 'non_determine', 100, NULL, NULL, 'https://alliancesdarna.ma/wp-content/uploads/menzah-benslimane-lot-terrain-a-vendre-rch2-.jpg', $j$["https://alliancesdarna.ma/wp-content/uploads/menzah-benslimane-lot-terrain-a-vendre-rch2-.jpg", "https://alliancesdarna.ma/wp-content/uploads/RIAD-MARRAKECH2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/BNIMELLAL-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/MENZAH2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/COLLINE2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/ALBASSATIN2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/CHWITER2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/HALALA2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/SAB2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/riadelkhier-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/mdiq2-340x194.jpg", "https://alliancesdarna.ma/wp-content/uploads/medhia2-340x194.jpg"]$j$::jsonb, 'Lot de terrain', 'Jardin', NULL, false, NULL, NULL, NULL, 'MAD', NULL, '4695cecd-b348-51d6-bb14-7d92e4ae0980', 'Alliances Darna', 'https://alliancesdarna.ma/', $j$[]$j$::jsonb, $j${"source_project_id": "96d55c35-b4f0-5faf-9986-cbf2d60f7255", "chridari_ref": "KRX-PRJ-f602ed858309", "projet_id_legacy": "KRX-PRJ-f602ed858309", "equipe_realisation_mentions": "Maître d'ouvrage: Alliances Darna", "url_source": "https://alliancesdarna.ma/qui-sommes-nous/", "seed_batch": "promoteurs_full_sifarah"}$j$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.projects x WHERE x.id = '96d55c35-b4f0-5faf-9986-cbf2d60f7255'::uuid OR x.attributes->>'source_project_id' = '96d55c35-b4f0-5faf-9986-cbf2d60f7255');
INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT '985fac80-33e0-53cb-847c-3fa24080e827'::uuid, '4695cecd-b348-51d6-bb14-7d92e4ae0980'::uuid, 'Service après vente', 'Chez Alliances Darna, nous croyons que l''histoire de chaque achat ne se termine pas à la remise des clés, mais qu''elle commence là. Notre engagement envers vous va au-delà de la simple transaction. Nous sommes fiers d''offrir un suivi complet après l''achat pour vous assurer une expérience résidentielle exceptionnelle à chaque étape de votre parcours. Notre Équipe Technique à Votre Service Notre priorité est d''offrir un suivi complet après l''achat. Notre équipe technique est spécialement dédiée à répondre aux besoins des acquéreurs. Elle réalise également un état des lieux détaillé avant la remise des clés pour garantir que tout est en ordre. Nous nous efforçons de rendre le processus d''achat aussi fluide que possible, en fournissant un soutien continu à nos clients. État des Lieux Approfondi pour Votre Tranquillité Avant la remise des clés, nous effectuons un état des lieux détaillé pour nous assurer que chaque détail est en ordre. Votre tranquillité d''esprit est notre priorité, et c''est pourquoi nous nous engageons à vous offrir un environnement résidentiel impeccable et fonctionnel dès le début. Votre Satisfaction, Notre Priorité Chez Alliances Darna, votre satisfaction est notre', NULL, NULL, '16 rue Ali Abderrazak', NULL, 'MA', NULL, NULL, 'immobilier', 'lotissement', 'lotissement', 'sur_plan', 'en_commercialisation', 15, NULL, NULL, 'https://alliancesdarna.ma/wp-content/uploads/ESCDA-24-FR-1.png', $j$["https://alliancesdarn