INSERT INTO public.projects (id, user_id, title, description, city, neighborhood, address, postal_code, country, latitude, longitude, category, subtype, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, team, attributes) SELECT 'bf9768b5-a795-541d-99bc-b2ffdd6903e9'::uuid, 'da6e7f67-d5a5-577b-82f3-6af1a1837ac5'::uuid, 'Résidence Riad Al Yassamine', 'La résidence Riad Al Yassamine propose des appartements dans le cadre du programme d''aide directe au logement, offrant un accès à la propriété dans des conditions avantageuses. Le projet comprend des appartements de 2 chambres avec salon, cuisine et salle de bain, ainsi que des locaux commerciaux, le tout dans un cadre de vie pratique, à proximité de toutes les commodités. Pour toute information complémentaire, nous vous invitons à nous contacter. La commercialisation à guichet ouvert à partir du 19 août 2026.', 'Oujda', NULL, 'u cœ... Plus d''infos Groupe AL OMRANE - Résidence Riad Al Yassamine العربية × Bienvenue SAO - Agence Heure de connexion', '60000', 'MA', NULL, NULL, 'immobilier', 'lotissement', 'lotissement', 'en_construction', 'en_commercialisation', 55, NULL, NULL, 'https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/image_gallery_line/alomrane/notre-reseau/al-omrane-region-de-l-oriental/produits/projets/residence-riad-al-yassamine/14385675-1-fre-FR/R%C3%A9sidence-Riad-Al-Yassamine.png', $j$["https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/image_gallery_line/alomrane/notre-reseau/al-omrane-region-de-l-oriental/produits/projets/residence-riad-al-yassamine/14385675-1-fre-FR/R%C3%A9sidence-Riad-Al-Yassamine.png", "https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/product_list/alomrane/notre-reseau/al-omrane-region-de-l-oriental/produits/projets/les-orchidees/14480455-1-fre-FR/Les-Orchid%